import XCTest
@testable import ClassingCore
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif
final class ByokTests: XCTestCase {
    func config() -> ByokConfiguration { var c = ByokConfiguration(ownerId: "local"); c.profiles = [ByokProfile(id: "qa", name: "问答", model: "qa-model"), ByokProfile(id: "vision", name: "识图", model: "vision-model", role: "VISION"), ByokProfile(id: "voice", name: "转写", model: "voice-model", role: "TRANSCRIPTION"), ByokProfile(id: "speech", name: "朗读", model: "tts-model", role: "SPEECH")]; c.chatId = "qa"; c.visionId = "vision"; c.transcriptionId = "voice"; c.speechId = "speech"; c.wearId = "vision"; c.enabled = true; return c }
    func testRoleSelectionAndWatchIsolation() throws { let c = config(); try c.validate(); let watch = try c.forWatch(); XCTAssertEqual(watch.profiles.count, 1); XCTAssertEqual(watch.profiles[0].role, "CHAT"); XCTAssertEqual(watch.chatId, "vision"); XCTAssertEqual(watch.ownerId, "local") }
    func testRemovalClearsSelectionsAndWrongRolesReject() throws { var c = config(); c.remove("qa"); XCTAssertFalse(c.enabled); XCTAssertTrue(c.chatId.isEmpty); c.chatId = "voice"; XCTAssertThrowsError(try c.validate()) }
    func testMetadataRejectsCredentialFields() throws { let c = config(); let value = try JSONValue.encode(c); XCTAssertFalse(try value.text().contains("apiKey")); var object = value.object; var profiles = object["profiles"]!.array; var p = profiles[0].object; p["apiKey"] = .string("not-real"); profiles[0] = .object(p); object["profiles"] = .array(profiles); XCTAssertThrowsError(try ByokConfiguration.decode(.object(object))) }
    func testActionFenceRequiresExactlyOneValidProposal() throws { let reply = "建议调整。\n```classing-course-actions\n{\"version\":1,\"actions\":[{\"operation\":\"create\",\"lesson\":{\"title\":\"数学\"}}]}\n```"; let result = try ByokActions.parse(reply); XCTAssertNotNil(result.course); XCTAssertNil(result.exam); XCTAssertEqual(result.display, "建议调整。"); XCTAssertThrowsError(try ByokActions.parse(reply + reply)); XCTAssertThrowsError(try ByokActions.parse("```classing-exam-actions invalid")) }
    func testKeysDoNotEnterSettingsSync() throws { var s = AppState(); s.settings["byokConfig"] = .object(["endpoint": .string("https://example.invalid/v1"), "model": .string("qa")]); s.settings["byokEnabled"] = .bool(true); try CloudSync.capture(&s); XCTAssertNil(s.cloud.records["mobile.settings"]?.first { $0.id.hasPrefix("byok") }) }
    func testTranscriptionAndSpeechUseDedicatedEndpoints() async throws { let transport = ByokTransport(); let client = try BYOKClient(endpoint: URL(string: "https://example.invalid/v1")!, model: "test-model", key: "private-test-key", transport: transport); let text = try await client.transcribe(Data([1,2,3])); XCTAssertEqual(text, "转写文字"); _ = try await client.speech("朗读文字", voice: "alloy"); let paths = await transport.paths; XCTAssertEqual(paths, ["/v1/audio/transcriptions", "/v1/audio/speech"]) }
    func testProviderErrorsNeverEchoKeys() async throws { let transport = ByokTransport(fail: true), client = try BYOKClient(endpoint: URL(string: "https://example.invalid/v1")!, model: "qa", key: "private-test-key", transport: transport); do { _ = try await client.speech("测试", voice: "alloy"); XCTFail("expected failure") } catch { XCTAssertFalse(error.localizedDescription.contains("private-test-key")) } }
    func testStreamingRedactsKeysAcrossChunkBoundaries() async throws { let transport = ByokTransport(), key = "private-test-key", client = try BYOKClient(endpoint: URL(string: "https://example.invalid/v1")!, model: "qa", key: key, transport: transport); let result = try await client.chat([.object(["role": .string("user"), "content": .string("问题")])], snapshot: .object([:])) { _ in }; XCTAssertEqual(result, "回答 [REDACTED] 完成"); XCTAssertFalse(result.contains(key)) }
}
private actor ByokTransport: HTTPTransport {
    var paths: [String] = []
    let fail: Bool
    init(fail: Bool = false) { self.fail = fail }
    func send(_ request: URLRequest, limit: Int) async throws -> HTTPResponse { paths.append(request.url!.path); if fail { return HTTPResponse(status: 500, data: Data("{\"message\":\"private-test-key\"}".utf8)) }; return HTTPResponse(status: 200, data: request.url!.path.contains("transcriptions") ? Data("{\"text\":\"转写文字\"}".utf8) : Data([1,2,3])) }
    func stream(_ request: URLRequest, onEvent: @escaping @Sendable (SSEEvent) async throws -> Void) async throws { for piece in ["回答 private-", "test-key 完成"] { let json = JSONValue.object(["choices": .array([.object(["delta": .object(["content": .string(piece)])])])]); try await onEvent(SSEEvent(event: "message", data: json.text(), id: nil)) }; try await onEvent(SSEEvent(event: "message", data: "[DONE]", id: nil)) }
}
